"""Independent protocol checker (development only).

Rebuilds the certificate network from PROTOCOL.md text, recomputes predictions,
thresholds, values and reports, and checks allocation validity, circulation
feasibility, residual potentials, the coverage cut and coverage maximality with
its own max flow implementation.
"""
import sys
from bisect import bisect_left, bisect_right
from collections import Counter, deque
from fractions import Fraction

