# --------------------------------------------------------------------- flow
def _mf(n, edges, s, t):
    """Plain Dinic; edges = list of [u,v,cap]; returns (value, residual caps)."""
    to = []
    cap = []
    adj = [[] for _ in range(n)]

    def add(u, v, c):
        adj[u].append(len(to)); to.append(v); cap.append(c)
        adj[v].append(len(to)); to.append(u); cap.append(0)

    for (u, v, c) in edges:
        add(u, v, c)
    flow = 0
    while True:
        level = [-1] * n
        level[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for a in adj[u]:
                if cap[a] > 0 and level[to[a]] < 0:
                    level[to[a]] = level[u] + 1
                    q.append(to[a])
        if level[t] < 0:
            break
        it = [0] * n

        def dfs(u, f):
            if u == t:
                return f
            while it[u] < len(adj[u]):
                a = adj[u][it[u]]
                v = to[a]
                if cap[a] > 0 and level[v] == level[u] + 1:
                    r = dfs(v, min(f, cap[a]))
                    if r:
                        cap[a] -= r
                        cap[a ^ 1] += r
                        return r
                it[u] += 1
            return 0
        while True:
            r = dfs(s, 10 ** 9)
            if not r:
                break
            flow += r
    seen = [False] * n
    stack = [s]
    seen[s] = True
    while stack:
        u = stack.pop()
        for a in adj[u]:
            if cap[a] > 0 and not seen[to[a]]:
                seen[to[a]] = True
                stack.append(to[a])
    return flow, seen


def arc_list(case, preds, low):
    """(tail, head, lower, capacity, cost) in the mandated order."""
    slots = case['slots']; flows = case['flows']; groups = case['groups']
    windows = case['windows']
    S = len(slots); J = len(windows); F = len(flows); G = len(groups)
    B, I = case['bucket']
    times = [s[0] for s in slots]
    W = 1 + J * times[-1]
    cvs = case['class_values']
    tail = []; head = []; lowr = []; capa = []; cost = []
    def A(u, v, l, h, c):
        tail.append(u); head.append(v); lowr.append(l); capa.append(h); cost.append(c)
    def an(s): return 2 + 3 * s
    def bn(s): return 3 + 3 * s
    def en(s): return 4 + 3 * s
    def wn(j): return 2 + 3 * S + j
    def zn(f): return 2 + 3 * S + J + f
    def hn(g): return 2 + 3 * S + J + F + g
    K = 2 + 3 * S + J + F + G
    for s in range(S):
        A(0, an(s), 0, I if s == 0 else slots[s][2], 0)
        A(an(s), bn(s), 0, B, 0)
        if s + 1 < S:
            A(bn(s), an(s + 1), 0, B, 0)
        A(bn(s), en(s), 0, slots[s][1], 0)
    thr = probability.window_thresholds(case['stats'], windows)
    dense = []
    for s in range(S):
        for j in range(J):
            if thr[j] > windows[j][5] and times[s] >= windows[j][1] and times[s] <= windows[j][2]:
                dense.append((s, j))
                A(en(s), wn(j), 0, 1, (times[s] - windows[j][1]) - windows[j][6] * cvs[preds[j]] * W)
    for j in range(J):
        A(wn(j), zn(windows[j][0]), 0, 1, 0)
    for f in range(F):
        h = 1 if flows[f][2] < 0 else hn(flows[f][2])
        A(zn(f), h, low[f], flows[f][1], 0)
    for g in range(G):
        h = 1 if groups[g][0] < 0 else hn(groups[g][0])
        A(hn(g), h, 0, groups[g][1], 0)
    A(1, 0, 0, J, 0)
    return tail, head, lowr, capa, cost, K, dense, thr, W


def check_case(case, preds, res, full_opt=True):
    slots = case['slots']; flows = case['flows']; groups = case['groups']
    windows = case['windows']
    S = len(slots); J = len(windows); F = len(flows); G = len(groups)
    times = [s[0] for s in slots]
    for key in ('predictions', 'reports', 'ratio', 'thresholds', 'assignment',
                'utility', 'age', 'flow', 'potential', 'cut'):
        if key not in res:
            raise Bad('missing ' + key)
    if set(res) != {'predictions', 'reports', 'ratio', 'thresholds',
                    'assignment', 'utility', 'age', 'flow', 'potential', 'cut'}:
        raise Bad('result keys')
    if res['predictions'] != preds:
        raise Bad('predictions mismatch')
    thr = probability.window_thresholds(case['stats'], windows)
    if res['thresholds'] != thr:
        raise Bad('thresholds mismatch')
    p, q = res['ratio']
    if type(p) is not int or type(q) is not int or q < 1 or p < 0 or p > q or q > 64:
        raise Bad('ratio shape')
    r = Fraction(p, q)
    if Fraction(p, q) != r or r > 1:
        raise Bad('ratio not lowest terms')
    low = [-((-p * flows[f][0]) // q) for f in range(F)]
    tail, head, lowr, capa, cost, K, dense, thr2, W = arc_list(case, preds, low)
    cv = case['class_values']
    value = [windows[j][6] * cv[preds[j]] for j in range(J)]
    asg = res['assignment']
    if len(asg) != J or any(type(a) is not int for a in asg):
        raise Bad('assignment shape')
    # assignment validity
    for j in range(J):
        s = asg[j]
        if s < 0:
            continue
        if not (0 <= s < S):
            raise Bad('slot range')
        if windows[j][5] >= thr[j]:
            raise Bad('gated window selected')
        if not (times[s] >= windows[j][1] and times[s] <= windows[j][2]):
            raise Bad('window not ready')
    cnt = Counter(windows[j][0] for j in range(J) if asg[j] >= 0)
    for f in range(F):
        if cnt[f] > flows[f][1]:
            raise Bad('flow ceiling')
    # group ceilings
    par = [g[0] for g in groups]
    def anc(g):
        seen = set()
        cur = g
        while cur >= 0:
            if cur in seen:
                raise Bad('cycle')
            seen.add(cur)
            yield cur
            cur = par[cur]
    for g in range(G):
        tot = sum(cnt[f] for f in range(F) if flows[f][2] == g)
        for h in anc(g):
            pass
    for g in range(G):
        tot = 0
        for f in range(F):
            fg = flows[f][2]
            if fg < 0:
                continue
            ok = False
            cur = fg
            while cur >= 0:
                if cur == g:
                    ok = True
                    break
                cur = par[cur]
            if ok:
                tot += cnt[f]
        if tot > groups[g][1]:
            raise Bad('group ceiling')
    U = sum(value[j] for j in range(J) if asg[j] >= 0)
    Ag = sum(times[asg[j]] - windows[j][1] for j in range(J) if asg[j] >= 0)
    if U != res['utility']:
        raise Bad('utility')
    if Ag != res['age']:
        raise Bad('age')
    rr = Fraction(1, 1)
    for f in range(F):
        rr = min(rr, Fraction(cnt[f], flows[f][0]))
    if rr > 1:
        rr = Fraction(1, 1)
    if rr != r:
        raise Bad('ratio does not agree with assignment (%s vs %s)' % (rr, r))
    # circulation
    fl = res['flow']
    if len(fl) != len(tail) or any(type(x) is not int for x in fl):
        raise Bad('flow shape %d vs %d' % (len(fl), len(tail)))
    bal = [0] * K
    for i in range(len(tail)):
        x = fl[i]
        if x < lowr[i] or x > capa[i]:
            raise Bad('arc bound %d' % i)
        bal[tail[i]] -= x
        bal[head[i]] += x
    if any(b != 0 for b in bal):
        raise Bad('conservation')
    # dense arcs mirror assignment
    for t, (s, j) in enumerate(dense):
        want = 1 if asg[j] == s else 0
        i = (len(tail) - len(dense))
        # locate dense block start
        pass
    dstart = None
    for i in range(len(tail)):
        if head[i] == 2 + 3 * S:
            dstart = i
            break
    if dstart is None:
        dstart = None
    if dense:
        # dense block = exactly len(dense) arcs preceding the window arcs
        start = len(tail) - (len(dense) + J + F + G + 1)
        for t, (s, j) in enumerate(dense):
            want = 1 if asg[j] == s else 0
            if fl[start + t] != want:
                raise Bad('dense arc mismatch %d' % t)
    # potentials
    pot = res['potential']
    if len(pot) != K or any(type(x) is not int for x in pot):
        raise Bad('potential shape')
    for v in pot:
        if v > 10 ** 60 or v < -10 ** 60:
            raise Bad('potential bound')
    for i in range(len(tail)):
        u = tail[i]; v = head[i]; x = fl[i]; c = cost[i]
        if x < capa[i] and c + pot[u] - pot[v] < 0:
            raise Bad('reduced cost forward arc %d' % i)
        if x > lowr[i] and -c + pot[v] - pot[u] < 0:
            raise Bad('reduced cost backward arc %d' % i)
    # cut / maximality
    if r == 1:
        if res['cut'] is not None:
            raise Bad('cut must be null')
    else:
        rset = sorted({Fraction(k, flows[f][0]) for f in range(F) for k in range(flows[f][0] + 1) if Fraction(k, flows[f][0]) <= 1})
        nxt = None
        for x in rset:
            if x > r:
                nxt = x
                break
        if nxt is None:
            raise Bad('no next ratio')
        low2 = [-((-nxt.numerator * flows[f][0]) // nxt.denominator) for f in range(F)]
        t2, h2, l2, c2, o2, K2, d2, th2, W2 = arc_list(case, preds, low2)
        cut = res['cut']
        if cut is None:
            raise Bad('cut missing')
        if len(set(cut)) != len(cut) or any((type(v) is not int or v < 0 or v >= K2) for v in cut):
            raise Bad('cut shape')
        inside = set(cut)
        ein = 0; eout = 0
        for i in range(len(t2)):
            u = t2[i]; v = h2[i]
            if u in inside and v not in inside:
                eout += c2[i]
            elif u not in inside and v in inside:
                ein += l2[i]
        if not (ein > eout):
            raise Bad('cut not an obstruction %d %d' % (ein, eout))
        if full_opt:
            ok2 = feas_check(K2 + 2, t2, h2, l2, c2, K2, K2 + 1, sum(low2))
            if ok2:
                raise Bad('next ratio actually feasible')
            ok1 = feas_check(K + 2, tail, head, lowr, capa, K, K + 1, sum(low))
            if not ok1:
                raise Bad('reported ratio infeasible?!')
    # reports
    rep = reports(case, preds, asg)
    cmp_reports(res['reports'], rep)
    return True


def feas_check(n, tail, head, low, capa, s, t, total):
    edges = []
    for i in range(len(tail)):
        edges.append((tail[i], head[i], capa[i] - low[i]))
    dem = [0] * n
    for i in range(len(tail)):
        if low[i]:
            dem[tail[i]] -= low[i]
            dem[head[i]] += low[i]
    for v in range(n):
        if dem[v] > 0:
            edges.append((s, v, dem[v]))
        elif dem[v] < 0:
            edges.append((v, t, -dem[v]))
    val, _ = _mf(n, edges, s, t)
    return val >= total


def reports(case, preds, asg):
    flows = case['flows']; windows = case['windows']
    ptrue = []; pprev = []
    per = {}
    for j in range(len(windows)):
        if asg[j] < 0:
            continue
        f = windows[j][0]
        ptrue.append(flows[f][3]); pprev.append(preds[j])
        per.setdefault(f, []).append(preds[j])
    strue = []; sprev = []
    for f, lst in per.items():
        c = Counter(lst)
        best = max(c.items(), key=lambda kv: (kv[1], -lst.index(kv[0])))
        strue.append(flows[f][3]); sprev.append(best[0])
    return {'packet': met(ptrue, pprev), 'stream': met(strue, sprev)}


def met(true, pred):
    m = [[0] * 7 for _ in range(7)]
    for t, p in zip(true, pred):
        m[t][p] += 1
    tp = [m[i][i] for i in range(7)]
    rows = [sum(m[i]) for i in range(7)]
    cols = [sum(m[i][i2] for i in range(7)) for i2 in range(7)]
    n = len(true)
    def rat(a, b):
        return Fraction(a, b) if b else Fraction(0)
    acc = rat(sum(tp), n) if n else Fraction(0)
    prec = [rat(tp[i], cols[i]) for i in range(7)]
    rec = [rat(tp[i], rows[i]) for i in range(7)]
    f1 = [rat(2 * tp[i], cols[i] + rows[i]) for i in range(7)]
    return {'confusion': m,
            'accuracy': acc / 1,
            'macro_precision': sum(prec) / 7,
            'macro_recall': sum(rec) / 7,
            'macro_f1': sum(f1) / 7}


def cmp_reports(got, want):
    for level in ('packet', 'stream'):
        g = got[level]; w = want[level]
        if set(g) != set(w):
            raise Bad('report keys')
        if g['confusion'] != w['confusion']:
            raise Bad('confusion ' + level)
        for k in ('accuracy', 'macro_precision', 'macro_recall', 'macro_f1'):
            if type(g[k]) not in (int, float):
                raise Bad('metric type')
            if abs(Fraction(g[k]) - w[k]) > Fraction(1, 10 ** 9):
                raise Bad('metric ' + k + ' ' + level)


def check_request(request, response):
    if response.get('version') != 3 or 'results' not in response:
        raise Bad('envelope')
    res = response['results']
    if len(res) != len(request['cases']):
        raise Bad('result count')
    import controller
    out = []
    for case, r in zip(request['cases'], res):
        preds = controller._predict(case['model'], case['windows'], case['flows'])
        out.append(check_case(case, preds, r))
    return out
